import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
} from "../motion";

export const fps = 25;

const COLORS = {
  deepBrown: "#1A0F08",
  oxblood: "#3D1410",
  amber: "#D97842",
  cream: "#F5E6D3",
  softWhite: "rgba(255,255,255,0.92)",
  muted: "rgba(245,230,211,0.55)",
  shadow: "#0A0503",
  bg: "#0A0503",
};

const TRANSITION = 20;

// ============ BACKGROUND ============
const Background: React.FC = () => {
  const frame = useCurrentFrame();
  const driftX = ambientDrift(frame, 8, 240, "bg-drift-x");
  const driftY = ambientDrift(frame, 6, 280, "bg-drift-y");
  const scale = 1 + frame * 0.0002;

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.bg }}>
      {/* Atmospheric base gradient */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(70% 55% at 50% 55%, ${COLORS.oxblood} 0%, ${COLORS.deepBrown} 45%, ${COLORS.bg} 100%)`,
          transform: `scale(${scale}) translate(${driftX}px, ${driftY}px)`,
        }}
      />
      {/* Warm side glow */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(40% 60% at 18% 40%, rgba(217,120,66,0.18), transparent 70%)`,
          filter: "blur(40px)",
          mixBlendMode: "screen",
        }}
      />
      {/* Vignette */}
      <AbsoluteFill
        style={{
          background:
            "radial-gradient(100% 80% at 50% 50%, transparent 40%, rgba(0,0,0,0.7) 100%)",
        }}
      />
      {/* Grain */}
      <AbsoluteFill
        style={{
          backgroundImage: `url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)' opacity='0.5'/></svg>")`,
          opacity: 0.06,
          mixBlendMode: "overlay",
        }}
      />
    </AbsoluteFill>
  );
};

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ============ LETTERBOX ============
