        zIndex: 10,
        pointerEvents: "none",
      }}
    />
    <div
      style={{
        position: "absolute",
        bottom: 0,
        left: 0,
        right: 0,
        height: "10%",
        background: `linear-gradient(0deg, ${COLORS.bg} 30%, transparent)`,
        zIndex: 10,
        pointerEvents: "none",
      }}
    />
  </>
);

// ============ SCENE 1: Anticipation opener ============
