  const subIn = springIn(frame, vfps, 130, "GENTLE");

  const driftY = ambientDrift(frame, 2, 180, "s1-title");
  const driftLabel = ambientDrift(frame, 1, 220, "s1-label");

  return (
    <AbsoluteFill>
      <Background />
      <AbsoluteFill
        style={{
          transform: `scale(${camScale}) translateY(${camY}px)`,
          fontFamily: "Inter, sans-serif",
