        {/* Faint amber pool, blurred — depth */}
        <div
          style={{
            position: "absolute",
            left: "8%",
            top: "30%",
            width: "55%",
            height: 700,
            background: `radial-gradient(closest-side, ${COLORS.amber}33, transparent 75%)`,
            filter: "blur(60px)",
            mixBlendMode: "screen",
          }}
        />

        {/* Small caps label, upper-left */}
        <div
          style={{
            position: "absolute",
            left: "10%",
            top: `calc(28% + ${driftLabel}px)`,
            opacity: labelIn,
            filter: `blur(${labelBlur}px)`,
            fontFamily: "Inter, sans-serif",
            fontSize: 34,
            fontWeight: 400,
            letterSpacing: "0.32em",
            textTransform: "uppercase",
            color: COLORS.muted,
          }}
        >
          A folktale, retold
        </div>

        {/* Hero, low-third, upper-left aligned */}
        <div
          style={{
            position: "absolute",
            left: "10%",
            top: `calc(40% + ${driftY}px)`,
            opacity: titleIn,
            transform: `translateY(${titleY}px)`,
            filter: `blur(${titleBlur}px)`,
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 280,
            fontWeight: 300,
            letterSpacing: "-0.025em",
            lineHeight: 0.95,
            color: COLORS.softWhite,
            textShadow: "0 8px 80px rgba(0,0,0,0.6)",
            maxWidth: "75%",
          }}
        >
          Tung Tung
          <br />
          <span
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontStyle: "italic",
              fontWeight: 300,
              color: COLORS.amber,
            }}
          >
            Sahur
          </span>
        </div>

        {/* Lower right small label */}
        <div
          style={{
            position: "absolute",
            right: "10%",
            bottom: "16%",
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [16, 0])}px)`,
            fontFamily: "Inter, sans-serif",
            fontSize: 24,
            fontWeight: 400,
            letterSpacing: "0.28em",
            textTransform: "uppercase",
            color: COLORS.muted,
            textAlign: "right",
          }}
        >
          Indonesia · 03:00 AM
        </div>
      </AbsoluteFill>
      <Letterbox />
    </AbsoluteFill>
  );
};

