                filter: `blur(${interpolate(line3In, [0, 1], [8, 0])}px)`,
                fontFamily: "'GT Walsheim', Inter, sans-serif",
                fontStyle: "italic",
                color: COLORS.amber,
              }}
            >
              calls the faithful.
            </div>
          </div>
        </div>
      </AbsoluteFill>
      <Letterbox />
    </AbsoluteFill>
  );
};

// ============ SCENE 3: The figure ============
