// ============ SCENE 4: The warning ============
const SceneFour: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const camScale = 1 + frame * 0.00035;

  const chapIn = springIn(frame, vfps, 15, "GENTLE");
  const lineIn = springIn(frame, vfps, 40, "GENTLE");
  const subIn = springIn(frame, vfps, 110, "GENTLE");

  // Data array for the three rules
  const RULES = [
    { num: "01", text: "Do not answer the first call." },
    { num: "02", text: "Do not answer the second." },
    { num: "03", text: "Never answer the third." },
  ];

  const driftY = ambientDrift(frame, 2, 200, "s4-body");

  return (
    <AbsoluteFill>
      <Background />
      <AbsoluteFill
        style={{
          transform: `scale(${camScale})`,
          fontFamily: "Inter, sans-serif",
        }}
      >
        {/* Chapter */}
        <div
          style={{
            position: "absolute",
            left: "10%",
            top: "14%",
            opacity: chapIn,
            transform: `translateY(${interpolate(chapIn, [0, 1], [12, 0])}px)`,
            fontFamily: "Inter, sans-serif",
            fontSize: 26,
            fontWeight: 400,
            letterSpacing: "0.32em",
            color: COLORS.amber,
            textTransform: "uppercase",
          }}
        >
          III. The Warning
        </div>

        {/* Hero line */}
        <div
          style={{
            position: "absolute",
            left: "10%",
            top: "23%",
            opacity: lineIn,
            transform: `translateY(${interpolate(lineIn, [0, 1], [30, 0])}px)`,
            filter: `blur(${interpolate(lineIn, [0, 1], [8, 0])}px)`,
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontSize: 130,
            fontWeight: 300,
            letterSpacing: "-0.02em",
            lineHeight: 1,
            color: COLORS.softWhite,
            maxWidth: "75%",
            textShadow: "0 6px 60px rgba(0,0,0,0.5)",
          }}
        >
          If he calls your name,
          <br />
          <span
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              fontStyle: "italic",
              color: COLORS.amber,
            }}
          >
            do not reply.
          </span>
        </div>

        {/* The three rules — staggered */}
        <div
          style={{
            position: "absolute",
            left: "10%",
            top: `calc(56% + ${driftY}px)`,
            display: "flex",
            flexDirection: "column",
            gap: 28,
            maxWidth: "75%",
          }}
        >
          {RULES.map((rule, i) => {
            const itemIn = staggeredSpring(
              frame,
              vfps,
              i,
              90,
              22,
              "GENTLE"
            );
            const ix = interpolate(itemIn, [0, 1], [-30, 0]);
            const ibl = interpolate(itemIn, [0, 1], [6, 0]);
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "baseline",
                  gap: 36,
                  opacity: itemIn,
                  transform: `translateX(${ix}px)`,
                  filter: `blur(${ibl}px)`,
                }}
              >
                <div
                  style={{
                    fontFamily: "Inter, sans-serif",
                    fontSize: 30,
                    fontWeight: 400,
                    letterSpacing: "0.28em",
                    color: COLORS.amber,
                    minWidth: 80,
                  }}
                >
                  {rule.num}
                </div>
                <div
                  style={{
                    fontFamily: "'GT Walsheim', Inter, sans-serif",
                    fontSize: 56,
                    fontWeight: 300,
                    letterSpacing: "-0.005em",
                    color: COLORS.softWhite,
                    lineHeight: 1.2,
                  }}
                >
                  {rule.text}
                </div>
              </div>
            );
          })}
        </div>

        {/* Lower-right whisper */}
        <div
          style={{
            position: "absolute",
            right: "10%",
            bottom: "14%",
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [12, 0])}px)`,
            fontFamily: "Inter, sans-serif",
            fontSize: 24,
            fontWeight: 400,
            letterSpacing: "0.28em",
            textTransform: "uppercase",
            color: COLORS.muted,
            textAlign: "right",
          }}
        >
          Or he will come for you.
        </div>
      </AbsoluteFill>
      <Letterbox />
    </AbsoluteFill>
  );
};

