// ============ MAIN COMPOSITION ============
const S1 = 200;
const S2 = 240;
const S3 = 280;
const S4 = 340;
const S5 = 230;

export const durationInFrames =
  20 + S1 + S2 + S3 + S4 + S5 + 25 + TRANSITION * 5;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={20 + TRANSITION}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={S1 + TRANSITION}>
        <SceneOne />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={S2 + TRANSITION}>
        <SceneTwo />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
